import os
import json
import uuid
from datetime import datetime, timezone
from flask import Flask, request, jsonify, send_from_directory
from flask_cors import CORS
from cerebras.cloud.sdk import Cerebras
import threading
import time

app = Flask(__name__)
CORS(app)

print("Backend server starting...")

# Initialize Cerebras client
cerebras_api_key = os.environ.get("CEREBRAS_API_KEY")
if not cerebras_api_key:
    print("Make sure to set your CEREBRAS_API_KEY environment variable!")

client = Cerebras(api_key=cerebras_api_key)

# Persistent storage for conversations
CONVERSATIONS_FILE = 'conversations.json'
conversations_db = {}
conversations_lock = threading.Lock()

def load_conversations():
    """Load conversations from file"""
    global conversations_db
    try:
        if os.path.exists(CONVERSATIONS_FILE):
            with open(CONVERSATIONS_FILE, 'r', encoding='utf-8') as f:
                conversations_db = json.load(f)
                print(f"Loaded {len(conversations_db)} conversations from storage")
        else:
            conversations_db = {}
    except Exception as e:
        print(f"Error loading conversations: {e}")
        conversations_db = {}

def save_conversations():
    """Save conversations to file"""
    try:
        with open(CONVERSATIONS_FILE, 'w', encoding='utf-8') as f:
            json.dump(conversations_db, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"Error saving conversations: {e}")

def generate_conversation_title(first_message):
    """Generate a conversation title from the first message"""
    if len(first_message) <= 30:
        return first_message
    return first_message[:27] + "..."

def get_ai_response(messages):
    """Get response from Cerebras AI"""
    try:
        formatted_messages = []
        for msg in messages:
            formatted_messages.append({
                "role": msg["role"],
                "content": msg["content"]
            })

        # Add system message to ensure Hungarian responses and maximum length
        system_message = {
            "role": "system",
            "content": "Te egy magyar nyelvű AI asszisztens vagy. MINDIG magyarul válaszolj, függetlenül attól, hogy milyen nyelven kérdeznek. Adj részletes, átfogó és hosszú válaszokat minden kérdésre. Használj ki minden rendelkezésre álló helyet a válaszadásra."
        }

        # Insert system message at the beginning
        ai_messages = [system_message] + formatted_messages

        response = client.chat.completions.create(
            messages=ai_messages,
            model="gpt-oss-120b",
            stream=False,
            max_completion_tokens=65000,
            temperature=0.3,  # Lower temperature for more consistent Hungarian responses
            top_p=0.9
        )

        return response.choices[0].message.content
    except Exception as e:
        print(f"AI API Error: {str(e)}")
        return f"Sajnálom, hiba történt az AI válasz generálása során. Kérem próbálja újra. Hiba részletei: {str(e)}"

@app.route('/')
def serve_index():
    """Serve the main HTML file"""
    return send_from_directory('.', 'index.html')

@app.route('/manifest.json')
def serve_manifest():
    """Serve PWA manifest"""
    manifest = {
        "name": "Jadelight - AI Chat App",
        "short_name": "Jadelight",
        "description": "AI-powered chat application",
        "start_url": "/",
        "display": "standalone",
        "background_color": "#000000",
        "theme_color": "#00ff88",
        "icons": [
            {
                "src": "/generated-icon.png",
                "sizes": "192x192",
                "type": "image/png"
            }
        ]
    }
    return jsonify(manifest)

@app.route('/api/conversations', methods=['GET'])
def get_conversations():
    """Get all conversations"""
    with conversations_lock:
        conversations_list = []
        for conv_id, conv_data in conversations_db.items():
            conversations_list.append({
                "id": conv_data["id"],
                "title": conv_data["title"],
                "created_at": conv_data["created_at"],
                "updated_at": conv_data["updated_at"],
                "messages": conv_data["messages"]
            })

        return jsonify({
            "conversations": sorted(conversations_list, key=lambda x: x["updated_at"], reverse=True)
        })

@app.route('/api/conversations', methods=['POST'])
def create_conversation():
    """Create a new conversation"""
    data = request.get_json()
    title = data.get('title', 'Új beszélgetés')

    with conversations_lock:
        conv_id = str(uuid.uuid4())
        now = datetime.now(timezone.utc).isoformat()

        conversation = {
            "id": conv_id,
            "title": title,
            "created_at": now,
            "updated_at": now,
            "messages": []
        }

        conversations_db[conv_id] = conversation
        save_conversations()

        return jsonify(conversation), 201

@app.route('/api/conversations/<conversation_id>', methods=['GET'])
def get_conversation(conversation_id):
    """Get a specific conversation"""
    with conversations_lock:
        if conversation_id not in conversations_db:
            return jsonify({"error": "Beszélgetés nem található"}), 404

        return jsonify(conversations_db[conversation_id])

@app.route('/api/conversations/<conversation_id>', methods=['DELETE'])
def delete_conversation(conversation_id):
    """Delete a conversation"""
    with conversations_lock:
        if conversation_id not in conversations_db:
            return jsonify({"error": "Beszélgetés nem található"}), 404

        del conversations_db[conversation_id]
        save_conversations()
        return jsonify({"message": "Beszélgetés törölve"}), 200

@app.route('/api/conversations/<conversation_id>/messages', methods=['POST'])
def send_message(conversation_id):
    """Send a message and get AI response"""
    try:
        data = request.get_json()
        user_message = data.get('message', '').strip()

        if not user_message:
            return jsonify({"error": "Az üzenet nem lehet üres"}), 400

        with conversations_lock:
            if conversation_id not in conversations_db:
                return jsonify({"error": "Beszélgetés nem található"}), 404

            conversation = conversations_db[conversation_id]
            now = datetime.now(timezone.utc).isoformat()

            # Add user message
            user_msg = {
                "role": "user",
                "content": user_message,
                "timestamp": now
            }
            conversation["messages"].append(user_msg)

            # Update conversation title if this is the first message
            if len(conversation["messages"]) == 1:
                conversation["title"] = generate_conversation_title(user_message)

            # Prepare messages for AI (limit to last 20 messages for context)
            recent_messages = conversation["messages"][-20:]

            # Get AI response
            ai_content = get_ai_response(recent_messages)

            # Add AI message
            ai_msg = {
                "role": "assistant",
                "content": ai_content,
                "timestamp": datetime.now(timezone.utc).isoformat()
            }
            conversation["messages"].append(ai_msg)

            # Update conversation timestamp
            conversation["updated_at"] = ai_msg["timestamp"]

            # Save to persistent storage
            save_conversations()

            return jsonify({
                "user_message": user_msg,
                "ai_message": ai_msg,
                "conversation": conversation
            })

    except Exception as e:
        print(f"Error in send_message: {str(e)}")
        return jsonify({"error": f"Hiba történt: {str(e)}"}), 500

@app.route('/api/conversations/<conversation_id>/messages/<int:message_index>', methods=['DELETE'])
def delete_message(conversation_id, message_index):
    """Delete a specific message from conversation"""
    with conversations_lock:
        if conversation_id not in conversations_db:
            return jsonify({"error": "Beszélgetés nem található"}), 404

        conversation = conversations_db[conversation_id]

        if message_index < 0 or message_index >= len(conversation["messages"]):
            return jsonify({"error": "Üzenet nem található"}), 404

        del conversation["messages"][message_index]
        conversation["updated_at"] = datetime.now(timezone.utc).isoformat()
        save_conversations()

        return jsonify({"message": "Üzenet törölve"}), 200

@app.route('/api/health', methods=['GET'])
def health_check():
    """Health check endpoint"""
    return jsonify({
        "status": "healthy",
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "conversations_count": len(conversations_db),
        "cerebras_configured": bool(cerebras_api_key)
    })

@app.route('/api/stats', methods=['GET'])
def get_stats():
    """Get application statistics"""
    with conversations_lock:
        total_messages = sum(len(conv["messages"]) for conv in conversations_db.values())

        return jsonify({
            "total_conversations": len(conversations_db),
            "total_messages": total_messages,
            "timestamp": datetime.now(timezone.utc).isoformat()
        })

@app.errorhandler(404)
def not_found(error):
    """Handle 404 errors"""
    return jsonify({"error": "Endpoint nem található"}), 404

@app.errorhandler(500)
def internal_error(error):
    """Handle 500 errors"""
    return jsonify({"error": "Belső szerverhiba"}), 500

@app.errorhandler(400)
def bad_request(error):
    """Handle 400 errors"""
    return jsonify({"error": "Hibás kérés"}), 400

if __name__ == '__main__':
    # Load existing conversations from storage
    load_conversations()

    # No demo conversations - start clean

    print(f"Starting Flask server on 0.0.0.0:5000")
    print(f"Cerebras API configured: {'Yes' if cerebras_api_key else 'No'}")
    app.run(host='0.0.0.0', port=5000, debug=True, threaded=True)

